visual.code:
p.test1 {
  width: 200px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: clip;
}
p.test2 {
  width: 200px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

p.test1 {
  word-break: normal;
}
p.test2 {
  word-break: break-all;
}

p.test1 {
  writing-mode: horizontal-tb;
}
span {
  writing-mode: vertical-rl;
}
